import { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import './JobDetails.css';

export default function JobDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [job, setJob] = useState(null);
  const fileInputRef = useRef(null); 

  useEffect(() => {
    fetch(`http://localhost:5000/api/jobs/${id}`)
      .then((res) => res.json())
      .then((data) => setJob(data))
      .catch((err) => console.error("Erreur:", err));
  }, [id]);

  const handleApplyClick = () => {
    fileInputRef.current.click();
  };

  // NOUVELLE VERSION : Envoi en Base64 (JSON)
  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      // Conversion en chaîne Base64
      const base64File = reader.result;

      try {
        const res = await fetch(`http://localhost:5000/api/apply/${id}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ cvBase64: base64File, fileName: file.name })
        });

        if (res.ok) {
          alert("Candidature envoyée avec succès !");
        } else {
          alert("Erreur lors de l'envoi du CV.");
        }
      } catch (err) {
        console.error("Erreur d'envoi:", err);
      }
    };
    reader.readAsDataURL(file); // Lance la conversion
  };

  if (!job) return <p className="details-loading">Chargement des détails...</p>;

  return (
    <div className="details-container">
      <button className="btn-back" onClick={() => navigate(-1)}>← Retour</button>
      <h1 className="details-title">{job.title}</h1>
      <h3 className="details-company">{job.company}</h3>
      <p className="details-description">{job.description}</p>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        style={{ display: 'none' }} 
        accept=".pdf,.doc,.docx"
      />

      <button className="btn-apply" onClick={handleApplyClick}>
        Postuler à cette offre
      </button>
    </div>
  );
}
